-- ============================================================================
-- PostgreSQL 17 — 新增「比賽記錄單」（MatchScoreSheets 表）
-- ----------------------------------------------------------------------------
-- 背景：每場比賽（MatchLog）的每一局一筆記錄單，Content 為 jsonb 文件（先發、個人數據、失誤、逐分 rally），
--       Version 供樂觀並行控制。局號 1~50，同一場比賽局號唯一。
-- 冪等：IF NOT EXISTS 建表／索引／外鍵，可重複執行。
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS "MatchScoreSheets" (
    "Id"              integer       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MatchLogId"      integer       NOT NULL,
    "SetIndex"        smallint      NOT NULL,
    "RecorderName"    varchar(64)   NULL,
    "Content"         jsonb         NOT NULL,
    "Version"         integer       NOT NULL DEFAULT 1,
    "CreatedAt"       timestamptz   NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),
    "UpdatedAt"       timestamptz   NULL,
    "CreatedByUserId" integer       NULL,
    "UpdatedByUserId" integer       NULL,
    CONSTRAINT "CK_MatchScoreSheets_SetIndex" CHECK ("SetIndex" BETWEEN 1 AND 50)
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_MatchScoreSheets_LogSet" ON "MatchScoreSheets"("MatchLogId","SetIndex");

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_MatchScoreSheets_MatchLog') THEN
        ALTER TABLE "MatchScoreSheets" ADD CONSTRAINT "FK_MatchScoreSheets_MatchLog"
            FOREIGN KEY ("MatchLogId") REFERENCES "MatchLogs"("Id") ON DELETE CASCADE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_MatchScoreSheets_UpdatedBy') THEN
        ALTER TABLE "MatchScoreSheets" ADD CONSTRAINT "FK_MatchScoreSheets_UpdatedBy"
            FOREIGN KEY ("UpdatedByUserId") REFERENCES "Users"("Id");
    END IF;
END $$;

COMMIT;
